3066	bool NotificationManager::update_notifications(GLCanvas3D& canvas)
3067	{
3068		// no update if not top window
3069		wxWindow* p = dynamic_cast<wxWindow*>(wxGetApp().plater());
3070		while (p->GetParent() != nullptr)
3071			p = p->GetParent();
3072		wxTopLevelWindow* top_level_wnd = dynamic_cast<wxTopLevelWindow*>(p);
3073		if (!top_level_wnd->IsActive())
3074			return false;
3075	
3076		// next_render() returns numeric_limits::max if no need for frame
3077		const int64_t max = std::numeric_limits<int64_t>::max();
3078		int64_t       next_render = max;
3079		const int64_t time_since_render = GLCanvas3D::timestamp_now() - m_last_render;
3080		bool		  request_render = false;
3081		// During render, each notification detects if its currently hovered and changes its state to EState::Hovered
3082		// If any notification is hovered, all restarts its countdown
3083		bool          hover = false;
3084		for (const std::unique_ptr<PopNotification>& notification : m_pop_notifications) {
3085			if (notification->is_hovered()) {
3086				hover = true;
3087				break;
3088			}
3089		}
3090		// update state of all notif and erase finished
3091		for (auto it = m_pop_notifications.begin(); it != m_pop_notifications.end();) {
3092			std::unique_ptr<PopNotification>& notification = *it;
3093			request_render |= notification->update_state(hover, time_since_render);
3094			next_render = std::min<int64_t>(next_render, notification->next_render());
3095			if (notification->get_state() == PopNotification::EState::Finished)
3096				it = m_pop_notifications.erase(it);
3097			else
3098				++it;
3099		}
3100	
3101		// delayed notifications
3102		for (auto it = m_waiting_notifications.begin(); it != m_waiting_notifications.end();) {
3103			// substract time
3104			if ((*it).remaining_time > 0)
3105				(*it).remaining_time -= time_since_render;
3106			if ((*it).remaining_time <= 0) {
3107				if ((*it).notification && (*it).condition_callback()) { // push notification, erase it from waiting list (frame is scheduled by push)
3108					(*it).notification->reset_timer();
3109					// if activate_existing returns false, we expect push to return true.
3110					if(!this->activate_existing((*it).notification.get()) || (*it).delay_interval == 0) {
3111						push_notification_data(std::move((*it).notification), 0);
3112						it = m_waiting_notifications.erase(it);
3113						continue;
3114					}
3115				}
3116				// not possible to push, delay for delay_interval
3117				(*it).remaining_time = (*it).delay_interval;
3118			}
3119			next_render = std::min<int64_t>(next_render, (*it).remaining_time);
3120			++it;
3121		}
3122	
3123		// request next frame in future
3124		if (next_render < max)
3125			canvas.schedule_extra_frame(int(next_render));
3126	
3127		return request_render;
3128	}
