3142	bool NotificationManager::activate_existing(const NotificationManager::PopNotification* notification)
3143	{
3144		NotificationType   new_type = notification->get_type();
3145		const std::string &new_text = notification->get_data().text1;
3146		for (auto it = m_pop_notifications.begin(); it != m_pop_notifications.end(); ++it) {
3147			if ((*it)->get_type() == new_type && !(*it)->is_finished()) {
3148				// multiple of one type allowed, but must have different text
3149				if (std::find(m_multiple_types.begin(), m_multiple_types.end(), new_type) != m_multiple_types.end()) {
3150					// If found same type and same text, return true - update will be performed on the old notif
3151					if ((*it)->compare_text(new_text) == false) {
3152						continue;
3153					}
3154				// multiple of one type allowed, but must have different text nad ObjectID
3155				} else if (new_type == NotificationType::SlicingWarning) {
3156					auto w1 = dynamic_cast<const ObjectIDNotification*>(notification);
3157					auto w2 = dynamic_cast<const ObjectIDNotification*>(it->get());
3158					if (w1 != nullptr && w2 != nullptr) {
3159						const NotificationData& data1 = w1->get_data();
3160						const NotificationData& data2 = w2->get_data();
3161						if (data1.sub_msg_id != data2.sub_msg_id)
3162							continue;
3163						//if (!(*it)->compare_text(new_text) || w1->object_id != w2->object_id) {
3164						//	continue;
3165						//}
3166					} else {
3167						continue;
3168					}
3169				}
3170				if (it != m_pop_notifications.end() - 1)
3171					std::rotate(it, it + 1, m_pop_notifications.end());
3172				return true;
3173			}
3174		}
3175		return false;
3176	}
