#pragma once

// SPIKE (persistent print issues): what OrcaSlicer currently says is wrong
// with the active plate, read from OrcaSlicer's own state every time that
// state may have changed. Nothing here decides whether something is a problem:
// each entry is the result of a native check (Print::validate, the print's
// step warnings, the instance's print-volume state, the slice result) or the
// one fact that only an event carries (why a slice failed).
//
// The monitor keeps no issue alive on its own. An entry exists while the
// native source still reports it, and is marked stale while OrcaSlicer has an
// edit it has not yet applied to the print.

#include "slic3r/GUI/JusPrin/Workspace/ProjectState.hpp"

#include <wx/event.h>
#include <wx/timer.h>

#include <cstdint>
#include <functional>
#include <map>
#include <memory>
#include <string>
#include <vector>

namespace Slic3r {
class Print;
class SlicingStatusEvent;
class SlicingProcessCompletedEvent;
namespace GUI {
class Plater;
class PartPlate;
}
} // namespace Slic3r

namespace Slic3r::GUI::JusPrin::PrintIssues {

enum class IssueSource : std::uint8_t { Validation, Placement, SliceStep, SliceResult, SliceFailure };
enum class IssueSeverity : std::uint8_t { Warning, Blocker };

const char* source_name(IssueSource source);
const char* severity_name(IssueSeverity severity);

struct PrintIssue
{
    // Built from the native source's own identifiers (check type, setting
    // key, step, message id, object ids), never from the message text.
    std::string   id;
    IssueSource   source{IssueSource::Validation};
    IssueSeverity severity{IssueSeverity::Warning};
    std::string   code;    // native type or step, empty when Orca has none
    std::string   setting; // the setting key Orca attached, if any
    std::string   message; // Orca's words, unchanged
    std::uint64_t plate{0};
    std::uint64_t object{0};   // ModelObject id; 0 for a plate-wide finding
    std::uint64_t instance{0}; // ModelInstance id; 0 when Orca names only the object
    std::string   object_name;
    // The native source no longer vouches for it: an edit is waiting to be
    // applied, or the slice it came from was invalidated.
    bool          stale{false};

    bool operator==(const PrintIssue& other) const;
};

struct PrintIssueSnapshot
{
    std::uint64_t session{0};
    // Advances whenever the list or its freshness changes.
    std::uint64_t generation{0};
    std::uint64_t plate{0};
    // False while OrcaSlicer holds an edit it has not validated yet. An empty
    // list with checked == false is "not known", never "all clear".
    bool          checked{false};
    bool          slicing{false};
    bool          sliced{false};
    std::vector<PrintIssue> issues;

    const PrintIssue* find(const std::string& id) const;
};

class PrintIssueMonitor final
{
public:
    explicit PrintIssueMonitor(Plater& plater);
    ~PrintIssueMonitor();

    PrintIssueMonitor(const PrintIssueMonitor&) = delete;
    PrintIssueMonitor& operator=(const PrintIssueMonitor&) = delete;

    const PrintIssueSnapshot& snapshot() const { return m_snapshot; }
    void set_changed_callback(std::function<void()> callback) { m_changed = std::move(callback); }

    // Reads the native state now instead of on the next loop turn. For tests
    // and for a click that must act on what is true at the click.
    void refresh_now();

    // Diagnostics for the spike's measurements.
    double        last_validate_ms() const { return m_last_validate_ms; }
    std::uint64_t validate_runs() const { return m_validate_runs; }
    std::uint64_t recomputes() const { return m_recomputes; }

private:
    struct SliceFailure
    {
        std::string                message;
        std::vector<std::uint64_t> objects; // ModelObject ids
        bool                       critical{false};
        std::uint64_t              project_change{0};
    };

    void schedule();
    void recompute();
    void collect_placement(PartPlate& plate, std::vector<PrintIssue>& issues) const;
    void collect_validation(PartPlate& plate, Print& print, std::vector<PrintIssue>& issues);
    void collect_steps(PartPlate& plate, const Print& print, std::vector<PrintIssue>& issues) const;
    void collect_result(PartPlate& plate, const Print& print, std::vector<PrintIssue>& issues) const;
    void collect_failure(PartPlate& plate, std::vector<PrintIssue>& issues) const;

    void on_slice_status(wxCommandEvent& event);
    void on_timer(wxTimerEvent& event);
    void on_slicing_update(SlicingStatusEvent& event);
    void on_process_completed(SlicingProcessCompletedEvent& event);

    Plater&                  m_plater;
    ProjectStateSubscription m_project_subscription;
    PrintIssueSnapshot       m_snapshot;
    std::function<void()>    m_changed;
    // Validation as of the last time the print was in step with the model and
    // no slice was running.
    std::vector<PrintIssue>  m_validation;
    std::map<std::uint64_t, SliceFailure> m_failures; // by plate id
    std::uint64_t            m_project_changes{0};
    bool                     m_scheduled{false};
    bool                     m_was_slicing{false};
    double                   m_last_validate_ms{0};
    std::uint64_t            m_validate_runs{0};
    std::uint64_t            m_recomputes{0};
    // Expires with the monitor, so a queued recompute is dropped.
    std::shared_ptr<PrintIssueMonitor*> m_self;
};

} // namespace Slic3r::GUI::JusPrin::PrintIssues

