IssueOverlay::IssueOverlay(GLCanvas3D& canvas, PrintIssueMonitor& monitor, Actions actions)
    : m_canvas(canvas), m_monitor(monitor), m_actions(std::move(actions)), m_self(std::make_shared<IssueOverlay*>(this))
{
    // The list changed without the scene changing: the canvas has to draw.
    m_monitor.set_changed_callback([this] { request_frame(); });
}

IssueOverlay::~IssueOverlay() { m_monitor.set_changed_callback({}); }

void IssueOverlay::request_frame()
{
    m_canvas.set_as_dirty();
    m_canvas.request_extra_frame();
}

void IssueOverlay::after_frame(std::function<void(IssueOverlay&)> action)
{
    // A click may change the selection or post a message; neither belongs
    // inside the canvas's render pass.
    wxGetApp().CallAfter([self = std::weak_ptr<IssueOverlay*>(m_self), action = std::move(action)]() {
        if (const auto overlay = self.lock())
            action(**overlay);
    });
}

void IssueOverlay::select(const std::string& issue_id)
{
    m_selected = issue_id;
    if (const PrintIssue* issue = m_monitor.snapshot().find(issue_id); issue != nullptr && m_actions.highlight)
        m_actions.highlight(*issue);
    request_frame();
}

void IssueOverlay::set_list_open(bool open)
{
    m_list_open = open;
    request_frame();
}

std::optional<std::pair<float, float>> IssueOverlay::anchor_of(const PrintIssue& issue) const
{
    const Model* model = m_canvas.get_model();
    if (model == nullptr || issue.object == 0)
        return std::nullopt;
    // The target's box in the scene as it is drawn now, so a drag that has
    // not been committed to the model still carries the bubble.
    BoundingBoxf3 box;
    for (const GLVolume* volume : m_canvas.get_volumes().volumes) {
        const int object_index = volume->object_idx(), instance_index = volume->instance_idx();
        if (object_index < 0 || object_index >= int(model->objects.size()))
            continue;
        const ModelObject* object = model->objects[object_index];
        if (object->id().id != issue.object || instance_index < 0 || instance_index >= int(object->instances.size()))
            continue;
        if (issue.instance != 0 && object->instances[instance_index]->id().id != issue.instance)
            continue;
        box.merge(volume->transformed_bounding_box());
    }
    if (!box.defined)
        return std::nullopt;

    const Camera& camera = wxGetApp().plater()->get_camera();
    const Eigen::Matrix4d to_clip = camera.get_projection_matrix().matrix() * camera.get_view_matrix().matrix();
    const Vec3d           top(box.center().x(), box.center().y(), box.max.z());
    const Eigen::Vector4d clip = to_clip * Eigen::Vector4d(top.x(), top.y(), top.z(), 1.0);
    if (clip.w() <= 1e-9)
        return std::nullopt; // behind the camera
    const std::array<int, 4>& viewport = camera.get_viewport();
    return std::make_pair(float((0.5 + 0.5 * clip.x() / clip.w()) * viewport[2]),
                          float((0.5 - 0.5 * clip.y() / clip.w()) * viewport[3]));
}

void IssueOverlay::render()
{
    m_frame = {};
    const ShellTheme* theme = brand_theme();
    if (theme == nullptr)
        return;
    const PrintIssueSnapshot& snapshot = m_monitor.snapshot();
    const ShellMetrics&       m        = theme->metrics();
    const ShellPalette&       p        = theme->palette(GUI_App::dark_mode());
    const float               scale    = wxGetApp().imgui()->get_style_scaling();
    const Size                canvas   = m_canvas.get_canvas_size();
    const float canvas_w = float(canvas.get_width()), canvas_h = float(canvas.get_height());
    const float inset = std::round(m.space_3 * scale), pad = std::round(m.space_3 * scale), gap = std::round(m.space_2 * scale);
    const float line = ImGui::GetTextLineHeight();

    if (m_selected.empty() == false && snapshot.find(m_selected) == nullptr)
        m_selected.clear(); // the native source stopped reporting it

    // -- The status pill ----------------------------------------------------
    std::size_t blockers = 0, current = 0;
    for (const PrintIssue& issue : snapshot.issues) {
        current += issue.stale ? 0 : 1;
        blockers += !issue.stale && issue.severity == IssueSeverity::Blocker ? 1 : 0;
    }
    std::string label;
    const wxColour* dot = &p.text_secondary;
    if (!snapshot.checked) {
        label = "Checking\xE2\x80\xA6"; // never "no issues" while Orca has not looked
    } else if (snapshot.issues.empty()) {
        label = "No print issues";
        dot   = &p.status_success;
    } else {
        label = std::to_string(snapshot.issues.size()) + (snapshot.issues.size() == 1 ? " print issue" : " print issues");
        if (blockers != 0)
            label += " \xC2\xB7 " + std::to_string(blockers) + " blocking";
        dot = current == 0 ? &p.text_secondary : blockers != 0 ? &p.status_danger : &p.status_warning;
    }
    m_frame.pill_text = label;
    const float dot_size = std::round(m.space_2 * scale);
    const ImVec2 label_size = ImGui::CalcTextSize(label.c_str());
    OverlayRect pill;
    pill.h = std::round(m.chip.height * scale);
    pill.w = pad + dot_size + gap + label_size.x + pad;
    pill.x = canvas_w - inset - pill.w;
    pill.y = inset;
    m_frame.pill = pill;
    begin_bare("##jusprin_issue_pill", pill);
    {
        ImDrawList& draw = *ImGui::GetWindowDrawList();
        ImGui::SetCursorScreenPos(ImVec2(pill.x, pill.y));
        if (ImGui::InvisibleButton("##pill", ImVec2(pill.w, pill.h)) && !snapshot.issues.empty())
            after_frame([](IssueOverlay& self) { self.set_list_open(!self.m_list_open); });
        panel(draw, pill, p, std::round(m.chip.radius * scale));
        draw.AddCircleFilled(ImVec2(pill.x + pad + dot_size / 2, pill.y + pill.h / 2), dot_size / 2, im_color(*dot));
        draw.AddText(ImVec2(pill.x + pad + dot_size + gap, pill.y + std::round((pill.h - label_size.y) / 2)), im_color(p.text_primary),
                     label.c_str());
    }
    ImGui::End();

    // -- The list -----------------------------------------------------------
    float below_pill = pill.y + pill.h + gap;
    if (m_list_open && !snapshot.issues.empty()) {
        m_frame.list_open = true;
        const float row_h = std::round(m.menu_row.height * scale) + line; // two lines of text
        OverlayRect list;
        list.w = std::round(kListWidthDip * scale);
        list.h = float(snapshot.issues.size()) * row_h + 2 * std::round(m.popover.padding_y * scale);
        list.x = canvas_w - inset - list.w;
        list.y = below_pill;
        begin_bare("##jusprin_issue_list", list);
        {
            ImDrawList& draw = *ImGui::GetWindowDrawList();
            panel(draw, list, p, std::round(m.popover.radius * scale));
            float y = list.y + std::round(m.popover.padding_y * scale);
            int   index = 0;
            for (const PrintIssue& issue : snapshot.issues) {
                const OverlayRect row{list.x + std::round(m.menu_row.side_inset * scale), y,
                                      list.w - 2 * std::round(m.menu_row.side_inset * scale), row_h};
                m_frame.rows.emplace_back(issue.id, row);
                ImGui::SetCursorScreenPos(ImVec2(row.x, row.y));
                ImGui::PushID(index++);
                const bool clicked = ImGui::InvisibleButton("##row", ImVec2(row.w, row.h));
                ImGui::PopID();
                if (ImGui::IsItemHovered() || issue.id == m_selected)
                    draw.AddRectFilled(ImVec2(row.x, row.y), ImVec2(row.x + row.w, row.y + row.h), im_color(p.surface_selected),
                                       std::round(m.menu_row.radius * scale));
                draw.AddCircleFilled(ImVec2(row.x + pad / 2 + dot_size / 2, row.y + row.h / 2), dot_size / 2, im_color(tone(issue, p)));
                const float text_x = row.x + pad / 2 + dot_size + gap;
                const std::string where = (issue.object_name.empty() ? std::string("Whole plate") : issue.object_name) +
                                          (issue.stale ? " \xC2\xB7 checking" : "");
                draw.PushClipRect(ImVec2(text_x, row.y), ImVec2(row.x + row.w - gap, row.y + row.h), true);
                draw.AddText(ImVec2(text_x, row.y + std::round((row.h - 2 * line) / 2)), im_color(p.text_primary),
                             first_line(issue.message).c_str());
                draw.AddText(ImVec2(text_x, row.y + std::round((row.h - 2 * line) / 2) + line), im_color(p.text_secondary), where.c_str());
                draw.PopClipRect();
                if (clicked)
                    after_frame([id = issue.id](IssueOverlay& self) { self.select(id); });
                y += row_h;
            }
        }
        ImGui::End();
        below_pill = list.y + list.h + gap;
    }

    // -- The bubble ---------------------------------------------------------
    const PrintIssue* issue = m_selected.empty() ? nullptr : snapshot.find(m_selected);
    if (issue == nullptr)
        return;

    // Every finding on the same target shares the bubble; none is dropped.
    std::vector<const PrintIssue*> group;
    for (const PrintIssue& other : snapshot.issues)
        if (other.object == issue->object && other.instance == issue->instance)
            group.push_back(&other);
    const int group_index = int(std::find(group.begin(), group.end(), issue) - group.begin());

    const auto anchor = anchor_of(*issue);
    const bool in_view = anchor && anchor->first >= 0 && anchor->first <= canvas_w && anchor->second >= 0 && anchor->second <= canvas_h;
    const bool docked  = !in_view;

    const bool busy    = m_actions.chat_busy && m_actions.chat_busy();
    const bool enabled = snapshot.checked && !issue->stale && !busy;

    const std::string severity = issue->stale ? "Checking\xE2\x80\xA6" : issue->severity == IssueSeverity::Blocker ? "Blocks printing" : "Warning";
    const std::string where    = issue->object == 0 ? "Whole plate" : issue->object_name + (anchor ? (in_view ? "" : " \xC2\xB7 out of view") : "");
    const std::string message  = trimmed(issue->message);
    const std::string pager    = group.size() > 1 ? std::to_string(group_index + 1) + " of " + std::to_string(group.size()) : std::string();
    const std::string note     = busy ? "The assistant is replying\xE2\x80\xA6" : std::string();

    OverlayRect bubble;
    bubble.w = std::round(kBubbleWidthDip * scale);
    const float wrap = bubble.w - 2 * pad;
    const ImVec2 message_size = ImGui::CalcTextSize(message.c_str(), nullptr, false, wrap);
    const ButtonRecipe& ask_recipe     = m.button.secondary;
    const ButtonRecipe& resolve_recipe = m.button.primary;
    const float button_h = std::round(std::max(ask_recipe.height, resolve_recipe.height) * scale);
    bubble.h = pad + line + gap + message_size.y + (note.empty() ? 0 : gap + line) + pad + button_h + pad;

    if (docked) {
        bubble.x = canvas_w - inset - bubble.w;
        bubble.y = below_pill;
    } else {
        const float leader = std::round(m.space_4 * scale);
        bubble.x = std::clamp(anchor->first - bubble.w / 2, inset, std::max(inset, canvas_w - inset - bubble.w));
        bubble.y = std::clamp(anchor->second - leader - bubble.h, inset, std::max(inset, canvas_h - inset - bubble.h));
    }

    m_frame.bubble          = true;
    m_frame.docked          = docked;
    m_frame.target_in_view  = in_view;
    m_frame.bubble_rect     = bubble;
    m_frame.issue_id        = issue->id;
    m_frame.group_index     = group_index;
    m_frame.group_size      = int(group.size());
    m_frame.actions_enabled = enabled;
    if (anchor) {
        m_frame.anchor_x = anchor->first;
        m_frame.anchor_y = anchor->second;
    }

    begin_bare("##jusprin_issue_bubble", bubble);
    {
        ImDrawList& draw = *ImGui::GetWindowDrawList();
        draw.PushClipRectFullScreen();
        if (!docked && anchor->second > bubble.y + bubble.h) {
            // The leader: from the bubble's lower edge to the object's top.
            const float foot_x = std::clamp(anchor->first, bubble.x + pad, bubble.x + bubble.w - pad);
            draw.AddLine(ImVec2(foot_x, bubble.y + bubble.h), ImVec2(anchor->first, anchor->second), im_color(tone(*issue, p)), 2.f * scale);
            draw.AddCircleFilled(ImVec2(anchor->first, anchor->second), dot_size / 2, im_color(tone(*issue, p)));
        }
        panel(draw, bubble, p, std::round(m.radius_container * scale));

        float y = bubble.y + pad;
        draw.AddCircleFilled(ImVec2(bubble.x + pad + dot_size / 2, y + line / 2), dot_size / 2, im_color(tone(*issue, p)));
        draw.AddText(ImVec2(bubble.x + pad + dot_size + gap, y), im_color(p.text_primary), severity.c_str());
        const ImVec2 severity_size = ImGui::CalcTextSize(severity.c_str());
        draw.PushClipRect(ImVec2(bubble.x, bubble.y), ImVec2(bubble.x + bubble.w - pad, bubble.y + bubble.h), true);
        draw.AddText(ImVec2(bubble.x + pad + dot_size + gap + severity_size.x + gap, y), im_color(p.text_secondary), where.c_str());
        draw.PopClipRect();
        if (!pager.empty()) {
            // The pager is the way to the group's other findings.
            const ImVec2 pager_size = ImGui::CalcTextSize(pager.c_str());
            const OverlayRect next{bubble.x + bubble.w - pad - pager_size.x - gap, y - gap / 2, pager_size.x + gap, line + gap};
            m_frame.next = next;
            if (button(draw, "##next", next, pager, std::round(m.radius_compact * scale), true, p.surface_subtle, p.surface_selected,
                       p.text_secondary, nullptr, p))
                after_frame([id = group[(group_index + 1) % group.size()]->id](IssueOverlay& self) { self.select(id); });
        }
        y += line + gap;
        draw.AddText(ImGui::GetFont(), ImGui::GetFontSize(), ImVec2(bubble.x + pad, y), im_color(p.text_primary), message.c_str(), nullptr,
                     wrap);
        y += message_size.y;
        if (!note.empty()) {
            y += gap;
            draw.AddText(ImVec2(bubble.x + pad, y), im_color(p.text_secondary), note.c_str());
            y += line;
        }
        y += pad;

        const float button_w = std::round((bubble.w - 2 * pad - gap) / 2);
        const OverlayRect ask{bubble.x + pad, y, button_w, button_h};
        const OverlayRect resolve{ask.x + ask.w + gap, y, bubble.w - 2 * pad - gap - button_w, button_h};
        m_frame.ask     = ask;
        m_frame.resolve = resolve;
        if (button(draw, "##ask", ask, "Ask AI", std::round(ask_recipe.radius * scale), enabled, p.action_secondary,
                   p.action_secondary_hover, p.action_secondary_text, &p.action_secondary_border, p))
            after_frame([id = issue->id](IssueOverlay& self) {
                if (self.m_actions.submit) self.m_actions.submit(id, IssueIntent::Explain);
            });
        if (button(draw, "##resolve", resolve, "Resolve with AI", std::round(resolve_recipe.radius * scale), enabled, p.action_primary,
                   p.action_primary_hover, p.text_on_action, nullptr, p))
            after_frame([id = issue->id](IssueOverlay& self) {
                if (self.m_actions.submit) self.m_actions.submit(id, IssueIntent::Resolve);
            });
        draw.PopClipRect();
    }
    ImGui::End();
}

