{
    using namespace PrintIssues;
    IssueSubmission result;
    if (m_print_issues == nullptr || m_workspace == nullptr || m_agent_pane == nullptr) {
        result.outcome = "unavailable";
        return result;
    }
    // What OrcaSlicer says at the press, not what the bubble was drawn from.
    m_print_issues->refresh_now();
    const PrintIssueSnapshot& issues = m_print_issues->snapshot();
    const PrintIssue*         issue  = issues.find(issue_id);
    if (issue == nullptr) {
        result.outcome = "expired";
        return result;
    }
    if (!issues.checked || issue->stale) {
        result.outcome = "unchecked";
        return result;
    }
    Agent::AgentHost& host = m_agent_pane->web_view().host();
    if (host.busy()) {
        result.outcome = "busy";
        return result;
    }

    const bool explain = intent == IssueIntent::Explain;
    const Workspace::WorkspaceSnapshot workspace = m_workspace->snapshot();
    nlohmann::json context{
        {"kind", "print_issue"},
        {"intent", explain ? "explain" : "resolve"},
        {"issue", {{"id", issue->id}, {"source", source_name(issue->source)}, {"severity", severity_name(issue->severity)},
                   {"code", issue->code}, {"setting", issue->setting}, {"message", issue->message}}},
        {"target", {{"scope", issue->instance != 0 ? "copy" : issue->object != 0 ? "object" : "plate"}, {"plateId", issue->plate}}},
        {"evidence", {{"checked", issues.checked}, {"generation", issues.generation}, {"sliced", issues.sliced}, {"slicing", issues.slicing}}},
        {"workspace", {{"sessionId", std::to_string(workspace.session.value())}, {"revision", workspace.revision}}}};
    if (issue->object != 0) {
        context["target"]["objectId"]   = issue->object;
        context["target"]["objectName"] = issue->object_name;
    }
    if (issue->instance != 0)
        context["target"]["copyId"] = issue->instance;

    std::string words = issue->message;
    while (!words.empty() && (words.back() == '\\n' || words.back() == ' '))
        words.pop_back();
    result.text = std::string(explain ? "Explain this issue and my options." : "Help fix this issue.") + "\\n\\n> " + words;
    result.context_json = context.dump();
    // One message per issue, intent, evidence and chat: a second press while
    // nothing has changed is the same question.
    result.client_message_id = std::string("issue-") + (explain ? "explain-" : "resolve-") +
                               std::to_string(std::hash<std::string>{}(issue->id)) + "-s" + std::to_string(issues.session) + "-g" +
                               std::to_string(issues.generation) + "-c" + m_persistence->document().active_conversation_id();

    // The reply has to be somewhere the person can see it.
    if (m_agent_pane_collapsed) {
        m_agent_pane_user_collapsed = false;
        set_agent_pane_collapsed(false);
    }
    std::string refusal;
    switch (host.submit_issue_message(result.client_message_id, result.text, result.context_json, &refusal)) {
    case Agent::AgentHost::SubmitResult::Started:   result.outcome = "started"; break;
    case Agent::AgentHost::SubmitResult::Queued:    result.outcome = "queued"; break;
    case Agent::AgentHost::SubmitResult::Duplicate: result.outcome = "duplicate"; break;
    case Agent::AgentHost::SubmitResult::Refused:   result.outcome = refusal; break;
    }
    return result;
}

